SELECT CAST(SUM(CASE WHEN DOC = '54' THEN 1 ELSE 0 END) AS REAL) / NULLIF(SUM(CASE WHEN DOC = '52' THEN 1 ELSE 0 END), 0) AS ratio
FROM schools
WHERE County = 'Orange' AND StatusType = 'Merged';

SELECT (SUM(CASE WHEN status = 'C' THEN amount ELSE 0 END) * 100.0 / SUM(amount)) AS percentage
FROM loan
WHERE amount < 100000;

SELECT CAST(SUM(CASE WHEN time IS NOT NULL THEN 1 ELSE 0 END) AS REAL) / COUNT(raceId) AS rate
FROM results
WHERE raceId IN (
    SELECT raceId FROM races
    WHERE year = 2008 AND name = 'Australian Grand Prix'
);

SELECT 100.0 * SUM(CASE WHEN Admission = '+' THEN 1 ELSE 0 END) / COUNT(*) AS percent_inpatient
FROM Patient
WHERE strftime('%Y', Birthday) BETWEEN '1930' AND '1940';
